mapper.select:
SELECT fb.id AS id, fb.title AS title, p.nickname AS authorName, fb.created_at AS createdAt, fb.updated_at AS updatedAt, fb.view_cnt AS viewCnt, fb.author_id AS userId, (SELECT COUNT(*) FROM user_like_board ulb WHERE ulb.board_id = fb.id) AS likeCnt, (SELECT COUNT(*) FROM free_comment fbc WHERE fbc.board_id = fb.id) AS commentCnt,
fbip.id AS img_id, fbip.saved_file_name AS img_name, fbip.path AS img_path, fbip.size AS img_size, fbip.content_type AS img_contentType FROM free_board fb JOIN user u ON fb.author_id = u.id JOIN profile p ON p.user_id = u.id LEFT JOIN free_board_image_property fbip ON fbip.id = ( SELECT sub_img.id FROM free_board_image_property sub_img WHERE sub_img.board_id = fb.id ORDER BY sub_img.id ASC LIMIT 1 ) WHERE fb.is_removed = false and fb.author_id = #{userId}
ORDER BY fb.created_at
ASC
DESC
LIMIT #{pageRequest.pageSize} OFFSET #{pageRequest.offset}

select *
from free_board
where id = #{id}
  and is_removed = false;

mapper.update:
UPDATE free_board

     title = #{title}, 
     content = #{content}, 
     view_cnt = #{viewCnt}, 
    updated_at = #{updatedAt}

WHERE id = #{id};

mapper.select:
select count(*)
